#import "VirtualPercussionist-Swift.h"

#include <utility>

namespace vp::store
{

namespace
{
    std::string str (NSString* s) { return s != nil ? std::string ([s UTF8String]) : std::string(); }

    Status convert (VPStatus* in)
    {
        Status out;
        switch (in.access)
        {
            case 1:  out.access = Access::locked;     break;
            case 2:  out.access = Access::trial;      break;
            case 3:  out.access = Access::subscribed; break;
            default: out.access = Access::checking;   break;
        }
        out.productsLoaded = in.productsLoaded;
        out.productsFailed = in.productsFailed;
        out.activePlanId = str (in.activePlanId);
        out.expiresAt = in.expiresAt;
        out.renewal = in.renewal == 1 ? Status::Renewal::renews
                    : in.renewal == 2 ? Status::Renewal::ends
                                      : Status::Renewal::unknown;
        out.hadSubscription = in.hadSubscription;
        for (VPPlan* p in in.plans)
        {
            Plan plan;
            plan.id = str (p.id);
            plan.price = str (p.price);
            plan.yearly = p.yearly;
            plan.lifetime = p.lifetime;
            plan.savePercent = static_cast<int> (p.savePercent);
            plan.trialEligible = p.trialEligible;
            plan.trialDays = static_cast<int> (p.trialDays);
            out.plans.push_back (std::move (plan));
        }
        return out;
    }
}

void start (std::function<void (const Status&)> onChange)
{
    [VPStore.shared start: ^(VPStatus* s)
    {
        if (onChange)
            onChange (convert (s));
    }];
}

void reloadProducts()
{
    [VPStore.shared reloadProducts];
}

void purchase (const std::string& planId,
               std::function<void (PurchaseResult, const std::string&)> done)
{
    [VPStore.shared purchase: [NSString stringWithUTF8String: planId.c_str()]
                        done: ^(NSInteger code, NSString* message)
    {
        const auto r = code == 0 ? PurchaseResult::success
                     : code == 1 ? PurchaseResult::pending
                     : code == 2 ? PurchaseResult::cancelled
                                 : PurchaseResult::failed;
        if (done)
            done (r, str (message));
    }];
}

void restore (std::function<void (bool)> done)
{
    [VPStore.shared restore: ^(BOOL ok)
    {
        if (done)
            done (ok);
    }];
}

void manage()
{
    [VPStore.shared manage];
}

